.visually-hidden,
.visually-hidden-focusable:not(:focus):not(:focus-within){width: 1px !important;
  height: 1px !important;
  padding: 0 !important;
  margin: -1px !important;
  overflow: hidden !important;
  clip: rect(0, 0, 0, 0) !important;
  white-space: nowrap !important;
  border: 0 !important;}
.visually-hidden:not(caption),
.visually-hidden-focusable:not(:focus):not(:focus-within):not(caption){position: absolute !important;}

:root{--bs-box-shadow:0 0.5rem 1rem rgba(0, 0, 0, 0.15);--bs-box-shadow-sm:0 0.125rem 0.25rem rgba(0, 0, 0, 0.075);--bs-box-shadow-lg:0 1rem 3rem rgba(0, 0, 0, 0.175)}
.shadow{box-shadow: var(--bs-box-shadow) !important;}
.shadow-sm{box-shadow: var(--bs-box-shadow-sm) !important;}
.shadow-lg{box-shadow: var(--bs-box-shadow-lg) !important;}
.shadow-none{box-shadow: none !important;}
